query organizationsNotifications {
  completedNotifications: organizationsNotifications(
    options: {filters: {completed: true}}
  ) {
    data {
      id
      organizationName
      organizationNumber
      type
      completed
      createdBy
      createdAt
      note
    }
    total
  }
  incompletedNotifications: organizationsNotifications(
    options: {filters: {completed: false}}
  ) {
    data {
      id
      organizationName
      organizationNumber
      type
      completed
      createdBy
      createdAt
