}

query searchJobs($page: Int!, $limit: Int!, $status: [JobStatus!], $jobType: [JobType!], $jobId: String, $requestId: String, $externalId: String) {
  searchJobs(
    filters: {limit: $limit, page: $page, status: $status, jobType: $jobType, jobId: $jobId, requestId: $requestId, externalId: $externalId}
  ) {
    total
    jobs {
      jobId
      jobType
      status
      requestId
      message
      createdAt
      updatedAt
      tries
      maxTries
      parameters
      requestId
      executionTime
      externalId
      canRetry
      canCancel
      delayUntil
