query viewerTasksWidget($organizationNumber: OrganizationID!, $isViewer: Boolean!, $withDelegatedTasks: Boolean!, $withSemineInvoices: Boolean!, $withNewExpense: Boolean!, $withOldExpense: Boolean!, $filters: SearchInvoiceInput!) {
  organization(id: $organizationNumber) {
    id
    threadNotificationsForViewer(onlyAssignedToViewer: true) @include(if: $isViewer)
    tasks(assignedToViewer: $isViewer, solved: false) {
      ...ViewerTasksWidget_tasks
    }
    delegatedTasks: tasks(createdByViewer: true, assignedToViewer: false) @include(if: $withDelegatedTasks) {
      ...ViewerTasksWidget_tasks
    }
    meetingsToSign: meetings(ended: true, signed: false) {
      ...ViewerTasksWidget_meetings
    }
  }
  invoiceExpensesToApproveByViewer(organizationId: $organizationNumber) @include(if: $withNewExpense) {
    ...ViewerTasksWidget_invoiceExpenses
  }
  expensesToApproveByViewer: searchExpenses(
    organizationId: $organizationNumber
    filters: {viewerShouldApprove: true}
  ) @include(if: $withOldExpense) {
    ...ViewerTasksWidget_expenses
  }
  invoicesToApproveByViewer: searchInvoices(
    organizationId: $organizationNumber
    filters: $filters
    failSilently: true
  ) @include(if: $withSemineInvoices) {
    invoices {
      ...ActiveInvoiceList
    }
    total
  }
  paymentsNeedingViewerAttention(organizationId: $organizationNumber) {
    staleDraftsCount
    pendingSignaturesCount
    firstStaleDraftBoardFeeId
    firstPendingSignatureBoardFeeId
  }
}
fragment ViewerTasksWidget_tasks on Task {
  id
  title
  description
  deadline
  solved
  deletedAt
  comments {
    id
    content
    createdAt
  }
  assignedTo {
    id
    isViewer
    name
    member {
      id
      firstName
      lastName
      phoneNumber
      email
      roles
    }
