}
fragment OrganizationAuditLog on AuditLog {
  id
  action
  createdAt
  parent {
    id
    title
  }
  createdBy {
    id
    personId
    name
  }
  payload {
    result
    data {
      action
      ...UpdateMemberAccount
      ...ConfirmPaymentOrder
      ...CreatePaymentOrder
      ...UpdatePaymentsLog
      ...BoardFeeTotalAmountChange
      __typename
    }
  }
}
fragment UpdateMemberAccount on UpdateMemberAccountLog {
  accountNumber
  personId
  name
  action
  confirmed
  oldAccountNumber
}
fragment ConfirmPaymentOrder on ConfirmPaymentOrder {
  paymentOrderId
}
fragment CreatePaymentOrder on CreatePaymentOrder {
  payments {
    amount
    paymentId
    recipient {
      name
